# ==============================================================================# 079_GOVERNANCE_DECISION_ENGINE.py## IOTEC GOVERNANCE DECISION ENGINE## Missão:# Avaliar solicitações de evolução da plataforma.## NÃO instala capacidades.# NÃO altera o sistema.# Apenas registra decisões de governança.# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class GovernanceDecisionEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS governance_decisions(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            decision_id TEXT,            capability TEXT,            priority TEXT,            commercial_impact REAL,            technical_risk REAL,            estimated_cost TEXT,            expected_roi TEXT,            decision TEXT,            justification TEXT,            approved_by TEXT,            status TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ----------------------------------------------------------------------    def _hash(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ----------------------------------------------------------------------    def register_decision(        self,        capability,        priority,        commercial_impact,        technical_risk,        estimated_cost,        expected_roi,        decision,        justification,        approved_by,        metadata=None    ):        metadata=metadata or {}        timestamp=datetime.utcnow().isoformat()        decision_id=hashlib.md5(            f"{timestamp}{capability}".encode()        ).hexdigest()        payload={            "timestamp":timestamp,            "decision_id":decision_id,            "capability":capability,            "priority":priority,            "commercial_impact":commercial_impact,            "technical_risk":technical_risk,            "estimated_cost":estimated_cost,            "expected_roi":expected_roi,            "decision":decision,            "justification":justification,            "approved_by":approved_by,            "status":"REGISTERED",            "metadata":metadata        }        assinatura=self._hash(payload)        self.conn.execute("""        INSERT INTO governance_decisions(            timestamp,            decision_id,            capability,            priority,            commercial_impact,            technical_risk,            estimated_cost,            expected_roi,            decision,            justification,            approved_by,            status,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["decision_id"],            payload["capability"],            payload["priority"],            payload["commercial_impact"],            payload["technical_risk"],            payload["estimated_cost"],            payload["expected_roi"],            payload["decision"],            payload["justification"],            payload["approved_by"],            payload["status"],            json.dumps(payload["metadata"],ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"]=assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    engine=GovernanceDecisionEngine()    resultado=engine.register_decision(        capability="BASE_EMPRESARIAL",        priority="CRÍTICA",        commercial_impact=98,        technical_risk=12,        estimated_cost="A DEFINIR",        expected_roi="ALTO",        decision="APROVADA PARA PLANEJAMENTO",        justification="Capacidade solicitada por múltiplos agentes e considerada estratégica.",        approved_by="IOTEC_GOVERNANCE",        metadata={            "origin":"078_KNOWLEDGE_EVOLUTION_ENGINE",            "next_step":"PLANEJAR_INTEGRAÇÃO"        }    )    print("="*80)    print("GOVERNANCE DECISION")    print("="*80)    for k,v in resultado.items():        print(f"{k:22}: {v}")    print("="*80)